package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__findDeserializer_TriageGen2Test {

    private DeserializationContext ctxt;
    private TypeIdResolver idResolver;
    private Map<String, JsonDeserializer<Object>> deserializers;
    private JavaType baseType;
    private BeanProperty property;
    private TypeFactory typeFactory;
    private TestTypeDeserializerBase testInstance;

    // Concrete implementation to expose protected method and provide stubs
    private static class TestTypeDeserializerBase extends TypeDeserializerBase {
        protected JsonDeserializer<Object> mockDefaultImpl;
        protected JavaType mockUnknownType;

        protected TestTypeDeserializerBase(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                         boolean typeIdVisible, JavaType defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        @Override
        public TypeDeserializer forProperty(BeanProperty prop) { return null; }
        @Override
        public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() { return null; }
        @Override
        public String baseTypeName() { return "test"; }

        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return mockDefaultImpl;
        }

        @Override
        protected JavaType _handleUnknownTypeId(DeserializationContext ctxt, String typeId) throws IOException {
            return mockUnknownType;
        }

        // Helper to access the protected method for testing
        public JsonDeserializer<Object> callFindDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return _findDeserializer(ctxt, typeId);
        }

        // Accessor for the internal map (simulated via reflection or by overriding if possible, 
        // but here we must rely on the fact that the method uses the field _deserializers)
        // Since we can't easily override the field, we rely on the behavior.
    }

    @Before
    public void setup() {
        ctxt = mock(DeserializationContext.class);
        idResolver = mock(TypeIdResolver.class);
        baseType = mock(JavaType.class);
        property = mock(BeanProperty.class);
        typeFactory = mock(TypeFactory.class);

        when(ctxt.getTypeFactory()).thenReturn(typeFactory);

        testInstance = new TestTypeDeserializerBase(baseType, idResolver, "type", true, null) {
            // Injecting the property because the method uses _property
            {
                try {
                    java.lang.reflect.Field propField = TypeDeserializerBase.class.getDeclaredField("_property");
                    propField.setAccessible(true);
                    propField.set(this, property);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
        };
    }

    @Test
    public void testFindDeserializer_AlreadyExists() throws IOException {
        String typeId = "exists";
        JsonDeserializer<Object> existingDeser = mock(JsonDeserializer.class);

        // Use reflection to pre-populate the private _deserializers map
        try {
            java.lang.reflect.Field mapField = TypeDeserializerBase.class.getDeclaredField("_deserializers");
            mapField.setAccessible(true);
            Map<String, JsonDeserializer<Object>> map = (Map<String, JsonDeserializer<Object>>) mapField.get(testInstance);
            map.put(typeId, existingDeser);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);
        assertEquals(existingDeser, result);
        verifyNoInteractions(idResolver);
    }

    @Test
    public void testFindDeserializer_TypeIdFound_NoGenerics() throws IOException {
        String typeId = "newType";
        JavaType foundType = mock(JavaType.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(foundType);
        when(foundType.hasGenericTypes()).thenReturn(false);
        when(foundType.getRawClass()).thenReturn(String.class);
        when(ctxt.findContextualValueDeserializer(any(JavaType.class), eq(property))).thenReturn(expectedDeser);

        // Mock baseType logic: _baseType.getClass() == type.getClass()
        // To satisfy this, we make baseType and foundType the same class type (SimpleType)
        // In real Jackson, they are often BeanDescription.Type or similar.
        // For testing purposes, we ensure the condition passes.
        when(baseType.getClass()).thenReturn(foundType.getClass());

        when(typeFactory.constructSpecializedType(eq(baseType), eq(String.class))).thenReturn(foundType);

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
        verify(typeFactory).constructSpecializedType(baseType, String.class);
    }

    @Test
    public void testFindDeserializer_TypeIdFound_WithGenerics() throws IOException {
        String typeId = "genericType";
        JavaType foundType = mock(JavaType.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(foundType);
        when(foundType.hasGenericTypes()).thenReturn(true);
        when(ctxt.findContextualValueDeserializer(eq(foundType), eq(property))).thenReturn(expectedDeser);
        when(baseType.getClass()).thenReturn(foundType.getClass());

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
        verify(typeFactory, never()).constructSpecializedType(any(), any());
    }

    @Test
    public void testFindDeserializer_TypeIdNull_DefaultImplFound() throws IOException {
        String typeId = "nullType";
        JsonDeserializer<Object> defaultDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        testInstance.mockDefaultImpl = defaultDeser;

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(defaultDeser, result);
    }

    @Test
    public void testFindDeserializer_TypeIdNull_DefaultImplNull_HandleUnknownTypeIdFound() throws IOException {
        String typeId = "unknownType";
        JavaType unknownType = mock(JavaType.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        testInstance.mockDefaultImpl = null;
        testInstance.mockUnknownType = unknownType;
        when(ctxt.findContextualValueDeserializer(eq(unknownType), eq(property))).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
    }

    @Test
    public void testFindDeserializer_AllPathsNull() throws IOException {
        String typeId = "totallyUnknown";

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        testInstance.mockDefaultImpl = null;
        testInstance.mockUnknownType = null;

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);

        assertNull(result);
    }

    @Test
    public void testFindDeserializer_BaseTypeNull_TypeIdFound() throws IOException {
        String typeId = "typeId";
        JavaType foundType = mock(JavaType.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        // Setup: baseType is null via constructor logic or reflection
        try {
            java.lang.reflect.Field baseTypeField = TypeDeserializerBase.class.getDeclaredField("_baseType");
            baseTypeField.setAccessible(true);
            baseTypeField.set(testInstance, null);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(foundType);
        when(ctxt.findContextualValueDeserializer(eq(foundType), eq(property))).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = testInstance.callFindDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
    }
}
